<?php if (($result['pages'] ?? 1) > 1): ?><nav class="proma-customer-360__pagination" aria-label="صفحه‌بندی"><span>صفحه <?= to_persian_digits($result['page']) ?> از <?= to_persian_digits($result['pages']) ?></span><div><?php if ((int) $result['page'] > 1): ?><a class="btn small secondary" data-customer-tab-page href="<?= e($pageUrl((int) $result['page'] - 1)) ?>">قبلی</a><?php endif; ?><?php if ((int) $result['page'] < (int) $result['pages']): ?><a class="btn small secondary" data-customer-tab-page href="<?= e($pageUrl((int) $result['page'] + 1)) ?>">بعدی</a><?php endif; ?></div></nav><?php endif; ?>
